package com.makemytrip.makemytrip.services;
import com.makemytrip.makemytrip.models.*;import com.makemytrip.makemytrip.repositories.*;import org.springframework.dao.DuplicateKeyException;import org.springframework.http.HttpStatus;import org.springframework.stereotype.Service;import org.springframework.web.server.ResponseStatusException;import org.springframework.data.mongodb.core.MongoTemplate;import org.springframework.data.mongodb.core.query.Criteria;import org.springframework.data.mongodb.core.query.Query;import org.springframework.data.mongodb.core.query.Update;
@Service public class ReviewService{private final ReviewRepository reviews;private final BookingRepository bookings;private final ReviewHelpfulVoteRepository helpfulVotes;private final MongoTemplate mongo;
 public ReviewService(ReviewRepository r,BookingRepository b,ReviewHelpfulVoteRepository votes,MongoTemplate mongo){reviews=r;bookings=b;helpfulVotes=votes;this.mongo=mongo;}
 public Review create(Review review,String user){if(review.getTargetType()==null||review.getBookingId()==null||review.getTargetId()==null)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"bookingId, targetType and targetId are required");if(review.getText()==null||review.getText().isBlank()||review.getText().length()>5000)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Review text must be between 1 and 5000 characters");validateRating(review.getRating());Booking b=bookings.findById(review.getBookingId()).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Booking not found"));if(!user.equals(b.getUserId()))throw new ResponseStatusException(HttpStatus.FORBIDDEN);if(b.getStatus()!=Booking.Status.COMPLETED)throw new ResponseStatusException(HttpStatus.CONFLICT,"Only completed bookings are eligible for review");if(!b.getProductId().equals(review.getTargetId())||!b.getType().equalsIgnoreCase(review.getTargetType().name()))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Review target does not match booking");if(reviews.existsByUserIdAndBookingId(user,review.getBookingId()))throw new ResponseStatusException(HttpStatus.CONFLICT,"Booking already reviewed");review.setUserId(user);review.setHelpfulCount(0);review.setStatus(Review.Status.PENDING);try{return reviews.save(review);}catch(DuplicateKeyException e){throw new ResponseStatusException(HttpStatus.CONFLICT,"Booking already reviewed");}}
 public Review edit(String id,Review update,String user){Review r=get(id);if(!user.equals(r.getUserId()))throw new ResponseStatusException(HttpStatus.FORBIDDEN);validateRating(update.getRating());if(update.getText()==null||update.getText().isBlank()||update.getText().length()>5000)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Review text must be between 1 and 5000 characters");r.setRating(update.getRating());r.setText(update.getText());r.setPhotos(update.getPhotos());r.setStatus(Review.Status.PENDING);r.touch();return reviews.save(r);}
 public void delete(String id,String user){Review r=get(id);if(!user.equals(r.getUserId()))throw new ResponseStatusException(HttpStatus.FORBIDDEN);reviews.delete(r);}
 public Review moderate(String id,Review.Status status){if(status==null)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"status is required");Review r=get(id);r.setStatus(status);return reviews.save(r);}
 public Review helpful(String id,String user){Review review=get(id);if(review.getStatus()!=Review.Status.APPROVED)throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Review not found");if(helpfulVotes.existsByReviewIdAndUserId(id,user))throw new ResponseStatusException(HttpStatus.CONFLICT,"Review already marked helpful by this user");ReviewHelpfulVote vote=new ReviewHelpfulVote();vote.setReviewId(id);vote.setUserId(user);try{helpfulVotes.save(vote);}catch(DuplicateKeyException e){throw new ResponseStatusException(HttpStatus.CONFLICT,"Review already marked helpful by this user");}var result=mongo.updateFirst(new Query(Criteria.where("_id").is(id).and("status").is(Review.Status.APPROVED)),new Update().inc("helpfulCount",1).set("updatedAt",java.time.Instant.now()),Review.class);if(result.getModifiedCount()!=1){helpfulVotes.delete(vote);throw new ResponseStatusException(HttpStatus.CONFLICT,"Review is no longer available");}return get(id);}
 public Review get(String id){return reviews.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Review not found"));}
 private void validateRating(int rating){if(rating<1||rating>5)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Rating must be 1-5");}
}
